{
  "root_causes": [
    {
      "service": "ts-basic-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.5) p50_ms, approx_quantile(duration/1e6,0.95) p95_ms, max(duration/1e6) max_ms FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravels' GROUP BY 1,2",
          "claim": "ts-basic-service queryForTravels p50 stays about 30 ms, but p95 rises to about 28.7 s with a 61.6 s maximum."
        },
        {
          "kind": "trace",
          "sql": "WITH t AS (SELECT trace_id FROM abnormal_traces WHERE service_name='ts-basic-service' AND span_name='BasicController.queryForTravels' ORDER BY duration DESC LIMIT 1) SELECT s.service_name, s.span_name, s.duration/1e6 ms, s.attr_status_code FROM abnormal_traces s JOIN t USING(trace_id) ORDER BY s.time LIMIT 25",
          "claim": "In the slowest trace, basic's queryForTravels takes 61.6 s while its child calls to route, train and station finish in about 40 ms total."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) v FROM abnormal_metrics WHERE service_name='ts-basic-service' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.usage','container.cpu.usage') GROUP BY 1",
          "claim": "ts-basic-service CPU and memory stay flat or lower in the abnormal period, so the slowness is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-basic-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-travel2-service') GROUP BY 1,2",
          "claim": "travel2's outgoing calls to basic take about 32.9 s at p95, matching basic's slow server time."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-travel-service') GROUP BY 1,2",
          "claim": "travel's calls to basic take about 8.6 s at p95, the same as basic's slow server spans."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-preserve-service') GROUP BY 1,2",
          "claim": "preserve's calls to basic take about 11.4 s at p95, and preserve's own p95 rises with them."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-route-plan-service') GROUP BY 1,2",
          "claim": "route-plan's calls to travel2 take about 20.9 s at p95, inheriting travel2's delay from basic."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-route-plan-service') GROUP BY 1,2",
          "claim": "route-plan's calls to travel take about 5.6 s at p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
