          "claim": "ui-dashboard's calls to travel-plan take about 38.4 s at p95, and ui-dashboard's calls to travel2 and travel are also slow."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id=p.trace_id WHERE c.service_name<>p.service_name AND p.service_name IN ('ts-ui-dashboard') GROUP BY 1,2",
          "claim": "ui-dashboard's calls to travel2 take about 33.5 s at p95 in the abnormal period, against about 0.5 s normally."
        }
      ]
    }
  ]
